package com.shiphappens.logistics.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="orders") public class LogisticsOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="order_number") private String orderNumber; @Column(name="external_reference") private String externalReference; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="customer_id") private Customer customer; @ManyToOne(cascade=CascadeType.PERSIST) @JoinColumn(name="pickup_address_id") private Address pickupAddress; @ManyToOne(cascade=CascadeType.PERSIST) @JoinColumn(name="delivery_address_id") private Address deliveryAddress; @Enumerated(EnumType.STRING) private Statuses.OrderStatus status=Statuses.OrderStatus.CREATED; @Column(name="created_at") private Instant createdAt; @PrePersist void created(){createdAt=Instant.now();} public Long getId(){return id;} public String getOrderNumber(){return orderNumber;} public void setOrderNumber(String v){orderNumber=v;} public String getExternalReference(){return externalReference;} public void setExternalReference(String v){externalReference=v;} public Customer getCustomer(){return customer;} public void setCustomer(Customer v){customer=v;} public Address getPickupAddress(){return pickupAddress;} public void setPickupAddress(Address v){pickupAddress=v;} public Address getDeliveryAddress(){return deliveryAddress;} public void setDeliveryAddress(Address v){deliveryAddress=v;} public Statuses.OrderStatus getStatus(){return status;} public void setStatus(Statuses.OrderStatus v){status=v;} public Instant getCreatedAt(){return createdAt;} }
